interface State { handle(context: Context): void }

class Context {
  private state: State
  constructor(s: State) { this.state = s }
  request() { this.state.handle(this) }
}

class ConcreteStateA implements State { handle(c: Context) { /* ... */ } }

class PaymentProcessor {
  private status: "pending" | "completed" | "failed"
  process() {
    switch (this.status) {
      case "pending": this.handlePending(); break
      case "completed": this.handleCompleted(); break
      case "failed": this.handleFailed(); break
    }
  }
}

